// Створіть програму, в якій ви оголосите змінні для кожного з примітивних типів даних: рядок, число, буль, null та undefined. Присвойте їм значення та виведіть кожну змінну на консоль.

let string = 'Не впевнена чи вірно зрозуміла завдання але нехай буде так';
let number = 13;
let boolean = true;
let mNull = null;
let undefined;

console.log("Рядок:", string);
console.log("Число:", number);
console.log("Булеве значення:", boolean);
console.log("Null:", mNull);
console.log("Undefined:", undefined);